#include "tangra_fc/command_arbitration.hpp"
#include <cassert>
#include <cmath>
#include <iostream>
using namespace tangra::fc;
static SourceCommand cmd(CommandSource s,std::uint64_t seq,std::uint64_t ts,std::uint32_t ttl,float roll=.1f){SourceCommand c{};c.source=s;c.sequence=seq;c.timestamp_ms=ts;c.ttl_ms=ttl;c.valid=true;c.setpoint.roll=roll;return c;}
int main(){CommandArbitrator a;assert(a.submit(cmd(CommandSource::PiSupervisor,10,100,100,.3f))==SubmitStatus::Accepted);assert(a.submit(cmd(CommandSource::PiSupervisor,10,101,100,.9f))==SubmitStatus::DuplicateSequence);auto d=a.select(110);assert(d.selected_source==CommandSource::PiSupervisor&&std::fabs(d.setpoint.roll-.3f)<1e-6f);assert(a.submit(cmd(CommandSource::PiSupervisor,9,102,100,-.8f))==SubmitStatus::OutOfOrderSequence);d=a.select(111);assert(std::fabs(d.setpoint.roll-.3f)<1e-6f);assert(a.submit(cmd(CommandSource::PiSupervisor,11,103,100,5.0f))==SubmitStatus::Accepted);d=a.select(112);assert(std::fabs(d.setpoint.roll-1.0f)<1e-6f);a.submit(cmd(CommandSource::BenchTest,1,105,100,.4f));d=a.select(112);assert(d.selected_source==CommandSource::BenchTest);auto safety=cmd(CommandSource::SafetyOverride,1,110,100,.9f);safety.force_safe=true;a.submit(safety);d=a.select(112);assert(d.selected_source==CommandSource::SafetyOverride&&d.safe_fallback);a.clear_all();d=a.select(1000);assert(d.safe_fallback&&d.selected_source==CommandSource::None);std::cout<<"PASS: arbitration replay/preemption semantics\n";}
